__attribute__((always_inline))
void rust_isa_msa_vshf(const uint8_t *a, const uint8_t *b,
                       const uint8_t *control, uint8_t *out) {
    v4i32 av = *(const v4i32 *)(const void *)a;
    v4i32 bv = *(const v4i32 *)(const void *)b;
    v4i32 cv = *(const v4i32 *)(const void *)control;
    v4i32 r;
    for (uint32_t i = 0; i < 4; i++) {
        uint32_t c = (uint32_t)cv[i];
        uint32_t k = (c & 0x3f) % 8;
        if (c & 0xc0) {
            r[i] = 0;
        } else if (k < 4) {
            r[i] = bv[k];
        } else {
            r[i] = av[k - 4];
        }
    }
    *(v4i32 *)(void *)out = r;
}

__attribute__((always_inline))
void rust_isa_msa_sld(const uint8_t *dest, const uint8_t *src, uint32_t index,
                      uint8_t *out) {
    v4i32 dv = *(const v4i32 *)(const void *)dest;
    v4i32 sv = *(const v4i32 *)(const void *)src;
    uint32_t n = index % 4;
    v4i32 r;
    for (uint32_t i = 0; i < 4; i++) {
        uint32_t k = i + n;
        r[i] = k < 4 ? sv[k] : dv[k - 4];
    }
    *(v4i32 *)(void *)out = r;
}

